PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS ra_accounts(id TEXT PRIMARY KEY,alias TEXT NOT NULL,recovery_hash TEXT NOT NULL UNIQUE,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS ra_sessions(token_hash TEXT PRIMARY KEY,account_id TEXT NOT NULL REFERENCES ra_accounts(id) ON DELETE CASCADE,expires_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS ra_sessions_account ON ra_sessions(account_id);
CREATE TABLE IF NOT EXISTS ra_projects(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES ra_accounts(id) ON DELETE CASCADE,name TEXT NOT NULL,contract_revision INTEGER NOT NULL DEFAULT 1,last_write_id TEXT NOT NULL DEFAULT '',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS ra_projects_owner ON ra_projects(owner_id);
CREATE TABLE IF NOT EXISTS ra_members(project_id TEXT NOT NULL REFERENCES ra_projects(id) ON DELETE CASCADE,account_id TEXT NOT NULL REFERENCES ra_accounts(id) ON DELETE CASCADE,role TEXT NOT NULL CHECK(role IN('owner','editor','viewer')),PRIMARY KEY(project_id,account_id));
CREATE TABLE IF NOT EXISTS ra_contracts(project_id TEXT NOT NULL REFERENCES ra_projects(id) ON DELETE CASCADE,revision INTEGER NOT NULL,document TEXT NOT NULL,document_hash TEXT NOT NULL,pack_version TEXT NOT NULL,pack_hash TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(project_id,revision));
CREATE TABLE IF NOT EXISTS ra_invites(token_hash TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES ra_projects(id) ON DELETE CASCADE,role TEXT NOT NULL CHECK(role IN('editor','viewer')),expires_at INTEGER NOT NULL,used_by TEXT,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS ra_capabilities(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES ra_projects(id) ON DELETE CASCADE,created_by TEXT REFERENCES ra_accounts(id) ON DELETE SET NULL,label TEXT NOT NULL,token_hash TEXT NOT NULL UNIQUE,created_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,revoked_at INTEGER);
CREATE INDEX IF NOT EXISTS ra_capabilities_project ON ra_capabilities(project_id);
CREATE TABLE IF NOT EXISTS ra_runs(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES ra_projects(id) ON DELETE CASCADE,capability_id TEXT NOT NULL REFERENCES ra_capabilities(id),mint_request_id TEXT NOT NULL,mint_payload_hash TEXT NOT NULL,run_key_hash TEXT NOT NULL,logical_id TEXT NOT NULL UNIQUE,contract_revision INTEGER NOT NULL,contract_hash TEXT NOT NULL,contract_document TEXT NOT NULL,pack_version TEXT NOT NULL,pack_hash TEXT NOT NULL,scenario TEXT NOT NULL,client TEXT NOT NULL,package_version TEXT NOT NULL,commit_id TEXT NOT NULL,replay_of TEXT,state TEXT NOT NULL DEFAULT 'open' CHECK(state IN('open','closing','finalized')),request_count INTEGER NOT NULL DEFAULT 0,last_request_id TEXT,created_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,finished_at INTEGER,runner_terminal TEXT,runner_observation TEXT,close_hash TEXT,verdict TEXT,result TEXT,UNIQUE(capability_id,mint_request_id));
CREATE INDEX IF NOT EXISTS ra_runs_project ON ra_runs(project_id,created_at DESC,id);
CREATE INDEX IF NOT EXISTS ra_runs_expiry ON ra_runs(expires_at);
CREATE TABLE IF NOT EXISTS ra_requests(id TEXT PRIMARY KEY,run_id TEXT NOT NULL REFERENCES ra_runs(id) ON DELETE CASCADE,attempt_id TEXT NOT NULL,sequence INTEGER NOT NULL,method TEXT NOT NULL,path_label TEXT NOT NULL,key_hash TEXT NOT NULL,payload_hash TEXT NOT NULL,body_bytes INTEGER NOT NULL,received_at INTEGER NOT NULL,resource_id TEXT,response_status INTEGER NOT NULL DEFAULT 0,response_policy TEXT NOT NULL DEFAULT 'pending',effect TEXT NOT NULL DEFAULT 'none',UNIQUE(run_id,attempt_id),UNIQUE(run_id,sequence));
CREATE INDEX IF NOT EXISTS ra_requests_run ON ra_requests(run_id,sequence);
CREATE TABLE IF NOT EXISTS ra_resources(id TEXT PRIMARY KEY,run_id TEXT NOT NULL REFERENCES ra_runs(id) ON DELETE CASCADE,key_hash TEXT NOT NULL,payload_hash TEXT NOT NULL,created_by_request TEXT NOT NULL REFERENCES ra_requests(id),committed_at INTEGER NOT NULL,UNIQUE(run_id,key_hash));
CREATE INDEX IF NOT EXISTS ra_resources_run ON ra_resources(run_id);
CREATE TABLE IF NOT EXISTS ra_rate_limits(rate_key TEXT PRIMARY KEY,count INTEGER NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS ra_checkout_sessions(id TEXT PRIMARY KEY,account_id TEXT NOT NULL REFERENCES ra_accounts(id) ON DELETE CASCADE,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS ra_billing_events(id TEXT PRIMARY KEY,payload_hash TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS ra_subscriptions(subscription_id TEXT PRIMARY KEY,account_id TEXT NOT NULL REFERENCES ra_accounts(id) ON DELETE CASCADE,customer_id TEXT NOT NULL,status TEXT NOT NULL,is_live INTEGER NOT NULL,expires_at INTEGER NOT NULL,last_event_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS ra_subscriptions_account ON ra_subscriptions(account_id,expires_at);
